package cn.huankan.event;

import java.util.*;import java.time.*;import java.math.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;

@Service public class TransmissionService {
 public static final String RULE="传导研究-1.0";
 private final JdbcTemplate db;private final MacroChangeService macro;private final ObjectMapper json;
 public TransmissionService(JdbcTemplate db,MacroChangeService macro,ObjectMapper json){this.db=db;this.macro=macro;this.json=json;}
 private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalArgumentException("研究结构无法编码");}}
 private Map<String,Object> view(Map<String,Object> row){try{row.put("report",json.readValue(row.get("report").toString(),Map.class));row.put("conditions",json.readValue(row.get("conditions").toString(),Map.class));return row;}catch(Exception e){throw new IllegalArgumentException("研究结构无法读取");}}
 public Object catalog(){return Map.of("version",TransmissionRules.VERSION,"templates",TransmissionRules.TEMPLATES,"status","机制模板待实际输入匹配，不表示已发生影响");}
 public Object input(UUID event){if(event==null)throw new IllegalArgumentException("事件ID必填");return db.queryForMap("SELECT m.evidence_id,m.series_id,m.observation_date,e.id event_id FROM financial_event e JOIN macro_observation m ON m.evidence_id=e.evidence_id WHERE e.id=?",event);}
 @Transactional public Object analyze(String owner,UUID evidence,Instant asOf){
  if(evidence==null||asOf==null||asOf.isAfter(Instant.now().plusSeconds(5)))throw new IllegalArgumentException("真实观测证据与截止时刻必填");
  var binding=db.queryForMap("SELECT m.series_id,m.observation_date,e.id event_id,f.id fact_id FROM macro_observation m JOIN financial_event e ON e.evidence_id=m.evidence_id JOIN fact_candidate f ON f.observation_id=m.evidence_id JOIN fact_evidence fe ON fe.fact_id=f.id AND fe.evidence_id=m.evidence_id JOIN raw_evidence r ON r.id=m.evidence_id JOIN source_registry sr ON sr.id=r.source_id WHERE sr.level='L0' AND r.raw_content_hash=encode(sha256(r.raw_content),'hex') AND m.evidence_id=? AND COALESCE((SELECT decision FROM fact_review v WHERE v.fact_id=f.id AND v.created_at<=? ORDER BY v.created_at DESC,v.id DESC LIMIT 1),f.verification_status) IN('FIELD_MATCHED','INDEPENDENT_SUPPORTED') AND f.created_at<=?",evidence,java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf));
  String ruleId="TRANSMISSION:"+owner;UUID fact=(UUID)binding.get("fact_id");var old=db.queryForList("SELECT * FROM impact_assessment WHERE fact_id=? AND rule_id=? AND rule_version=? AND as_of=?",fact,ruleId,RULE,java.sql.Timestamp.from(asOf));if(!old.isEmpty())return view(old.getFirst());
  String series=binding.get("series_id").toString();LocalDate period=((java.sql.Date)binding.get("observation_date")).toLocalDate();var detail=macro.detail(series,0,null,period,asOf,null);var rows=(List<Map<String,Object>>)detail.get("observations");
  if(rows==null||rows.size()<2||!Objects.equals(rows.getFirst().get("evidence_id"),evidence)||rows.getFirst().get("metadata")==null||rows.get(1).get("metadata")==null)throw new IllegalArgumentException("两期可核验原始观测不足或当前证据不是截止范围最新版本");
  var calc=new LinkedHashMap<String,Object>((Map<String,Object>)((Map<String,Object>)detail.get("calculations")).get("previous"));if(calc.get("delta")==null)throw new IllegalArgumentException("当前两期口径或日历不连续，不能运行传导机制");
  calc.put("calculated_at",asOf.toString());String calculationId=db.queryForObject("SELECT encode(sha256(convert_to(?::jsonb::text,'UTF8')),'hex')",String.class,encode(calc));calc.put("calculation_id",calculationId);var metadata=(Map<String,String>)rows.getFirst().get("metadata");String variable=TransmissionRules.variable(series,metadata);if(variable.equals("UNKNOWN"))throw new IllegalArgumentException("该真实变量尚无审核规则映射，不从标题猜测");
  var inputs=new LinkedHashMap<String,Object>();inputs.put("event_id",binding.get("event_id"));inputs.put("fact_id",fact);var frozenRows=new ArrayList<Map<String,Object>>();for(var original:rows.subList(0,2)){var copy=new LinkedHashMap<String,Object>(original);copy.replaceAll((k,v)->v instanceof java.sql.Date d?d.toString():v instanceof java.sql.Timestamp t?t.toInstant().toString():v);frozenRows.add(copy);}inputs.put("observations",frozenRows);inputs.put("calculation",calc);inputs.put("definition",detail.get("definition"));inputs.put("as_of",asOf.toString());inputs.put("owner",owner);
  // Both endpoint identities and the latest review must be verified at the cutoff.
  var relations=db.queryForList("SELECT er.id,er.type,er.relation_kind,er.subject_id,er.object_id,er.evidence_id,r.source_url,r.raw_content_hash,er.explanation FROM entity_relation er JOIN financial_entity a ON a.id=er.subject_id JOIN financial_entity b ON b.id=er.object_id JOIN raw_evidence r ON r.id=er.evidence_id JOIN source_license l ON l.source_id=r.source_id WHERE er.status='VERIFIED' AND a.status='VERIFIED' AND b.status='VERIFIED' AND er.relation_kind IN('BUSINESS_FACT','INDUSTRY_MEMBERSHIP','ACCOUNTING_CONSOLIDATION','LEGAL_IDENTITY') AND l.status='APPROVED' AND l.storage_allowed AND l.display_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) AND r.collected_at<=? AND r.ingested_at<=? AND r.published_at<=? AND er.disclosed_at<=? AND (er.effective_from IS NULL OR er.effective_from<=?) AND (er.effective_until IS NULL OR er.effective_until>?) AND (SELECT h.decision FROM relation_review_history h WHERE h.relation_id=er.id AND h.created_at<=? ORDER BY h.created_at DESC,h.id DESC LIMIT 1)='ACCEPT' AND r.raw_content_hash=encode(sha256(r.raw_content),'hex') AND EXISTS(SELECT 1 FROM event_entity ee WHERE ee.event_id=? AND ee.status='VERIFIED' AND (ee.entity_id=er.subject_id OR ee.entity_id=er.object_id))",java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),binding.get("event_id"));
  inputs.put("verified_relations",relations);String frozen=db.queryForObject("SELECT ?::jsonb::text",String.class,encode(inputs));String hash=db.queryForObject("SELECT encode(sha256(convert_to(?,'UTF8')),'hex')",String.class,frozen);
  var candidates=TransmissionRules.candidates(variable,metadata,new BigDecimal(calc.get("delta").toString()));var report=new LinkedHashMap<String,Object>();report.put("owner",owner);report.put("title",series.equals("EXR.D.USD.EUR.SP00.A")?"欧元兑美元参考汇率变化及潜在传导机制研究":"官方宏观变化及潜在传导机制研究");report.put("inputs",inputs);report.put("series_id",series);report.put("event_id",binding.get("event_id"));report.put("direction",TransmissionRules.direction(variable,metadata,new BigDecimal(calc.get("delta").toString())));report.put("fact_status","两期原始CSV字段核验通过；独立支持另行核查");report.put("calculation",calc);report.put("mechanisms",candidates);report.put("mechanism_catalog",TransmissionRules.TEMPLATES);report.put("entities",List.of());report.put("verified_relations",relations);report.put("exposure_status","尚无可核验的企业经营敞口证据");report.put("market_status","市场反应尚未验证");report.put("market_validation",List.of());report.put("generated_by","确定性规则引擎，未执行AI");report.put("research_version",RULE);report.put("mechanism_version",TransmissionRules.VERSION);report.put("input_hash",hash);report.put("source_boundary","官方参考汇率不是实时可成交报价；机制匹配不确认经济因果或公司利润");report.put("status_dictionary",List.of("机制适用条件满足","机制适用条件部分满足","证据不足","存在反面证据","假设待验证","市场结果已验证","假设已失效"));
  var paths=new ArrayList<Map<String,Object>>();for(var c:candidates){String mechanism=c.get("mechanism_id").toString();paths.add(Map.of("id",mechanism,"nodes",List.of(Map.of("id","fact","kind","FACT","status","已核验","evidence_ids",List.of(rows.getFirst().get("evidence_id"),rows.get(1).get("evidence_id"))),Map.of("id","derived","kind","DERIVED","parent","fact","status","可复算","calculation_id",calculationId),Map.of("id",mechanism,"kind","MECHANISM","parent","derived","status","机制适用条件部分满足"),Map.of("id",mechanism+":hypothesis","kind","HYPOTHESIS","parent",mechanism,"status","假设待验证"),Map.of("id",mechanism+":market","kind","MARKET_VALIDATION","parent",mechanism+":hypothesis","status","市场反应尚未验证"))));}report.put("paths",paths);report.put("industry_status","产业适用性须核验真实业务范围，未确认行业影响");report.put("monitor_conditions",List.of("后续同口径官方观测及修订","企业币种收入、成本、融资及对冲披露","合同重定价与会计折算期间","取得合法市场观测后独立验证"));
  var conditions=Map.of("owner",owner,"input_hash",hash,"fact_evidence_verified",true,"company_exposure_verified",false,"market_verified",false);UUID id=UUID.randomUUID();db.update("INSERT INTO impact_assessment(id,fact_id,rule_id,rule_version,as_of,input_evidence_id,input_hash,conditions,report) VALUES(?,?,?,?,?,?,?,?::jsonb,?::jsonb) ON CONFLICT DO NOTHING",id,fact,ruleId,RULE,java.sql.Timestamp.from(asOf),evidence,hash,encode(conditions),encode(report));return view(db.queryForMap("SELECT * FROM impact_assessment WHERE fact_id=? AND rule_id=? AND rule_version=? AND as_of=?",fact,ruleId,RULE,java.sql.Timestamp.from(asOf)));
 }
 public Object query(String owner,UUID id,int page){if(page<0||page>10000)throw new IllegalArgumentException("研究分页无效");var rows=db.queryForList("SELECT * FROM impact_assessment WHERE rule_version=? AND report->>'owner'=? AND (?::uuid IS NULL OR id=?) ORDER BY created_at DESC,id LIMIT 50 OFFSET ?",RULE,owner,id,id,page*50);rows.forEach(this::view);return rows;}
 public Object reproduce(String owner,UUID id){var rows=(List<Map<String,Object>>)query(owner,id,0);if(rows.size()!=1)throw new IllegalArgumentException("没有当前身份的研究快照");var row=rows.getFirst();var report=(Map<String,Object>)row.get("report");String hash=db.queryForObject("SELECT encode(sha256(convert_to((report->'inputs')::text,'UTF8')),'hex') FROM impact_assessment WHERE id=?",String.class,id);var inputs=(Map<String,Object>)report.get("inputs");var observations=(List<Map<String,Object>>)inputs.get("observations");var a=observation(observations.getFirst(),report.get("series_id").toString());var b=observation(observations.get(1),a.series());var recalculated=MacroChangeEngine.calculate(a,b,true);var saved=(Map<String,Object>)report.get("calculation");boolean exact=List.of("delta","relative_pct","basis_points","current_value","previous_value").stream().allMatch(k->Objects.equals(saved.get(k),recalculated.get(k)));boolean mechanisms=Objects.equals(report.get("mechanisms"),TransmissionRules.candidates(TransmissionRules.variable(a.series(),a.metadata()),a.metadata(),new BigDecimal(recalculated.get("delta").toString())));return Map.of("reproduced",hash.equals(row.get("input_hash"))&&exact&&mechanisms,"input_hash",hash,"calculation_matches",exact,"mechanisms_match",mechanisms,"rule_version",RULE);}
 private MacroChangeEngine.Observation observation(Map<String,Object> r,String series){return new MacroChangeEngine.Observation(r.get("evidence_id").toString(),series,LocalDate.parse(r.get("observation_date").toString()),new BigDecimal(r.get("original_value").toString()),(Map<String,String>)r.get("metadata"));}
}
